const unsigned rc_functionCount = sizeof(rc_functions) / sizeof(rc_functions[0]) - 1u;

rc_fn rc_lookup(u32 addr)
{
    unsigned lo = 0, hi = rc_functionCount;

    while (lo < hi)
    {
        unsigned mid = (lo + hi) / 2u;
        if (rc_functions[mid].addr == addr) return rc_functions[mid].fn;
        if (rc_functions[mid].addr < addr) lo = mid + 1u;
        else hi = mid;
    }
    return 0;
}

/* The function that owns an address: a call can land in the middle of a body, which is how the
 * engine's own opcode and jump tables work. Every instruction is a dispatch case there. */
const rc_entry *rc_containing(u32 addr)
{
    unsigned lo = 0, hi = rc_functionCount;

    while (lo < hi)
    {
        unsigned mid = (lo + hi) / 2u;
        if (rc_functions[mid].addr <= addr) lo = mid + 1u;
        else hi = mid;
    }
    if (lo == 0) return 0;
    const rc_entry *e = &rc_functions[lo - 1u];
    return addr < e->end ? e : 0;
}
